/* Find the palindrome words from the sentence and print them and also count
 * 
 * Input:
 * ----------------
 * My name is nitin and I can speak malayalam
 * 
 * Output:
 * ----------------
 * nitin
 * I
 * malayalam
 * 3
 */

import java.util.*;
public class Palindrome_in_String
{
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a string: ");
        String s = sc.nextLine();
        String[] pal = findPalindrome(s);
        if(pal!=null)
        {
            System.out.println("The palindroms are :");
            for (int i = 0; i < pal.length; i++) {
                System.out.println(pal[i]);
            }
            System.out.println("The number of palindrom words: "+pal.length);
        }
        else
        {
            System.out.println("No such palindrom words");
        }

    }
    public static boolean isPalindrome(String n)
    {
        for (int i = 0; i < n.length(); i++) 
        {
            if(n.charAt(i) != n.charAt(n.length()-i-1))
            {
                return false;
            }
        }
        return true;
    }
    public static String[] findPalindrome(String s)
    {
        String[] arr = s.split(" ");
        String[] pal = new String[0];
        for (int i = 0; i < arr.length; i++) {
            if(isPalindrome(arr[i]))
            {
                pal = Arrays.copyOf(pal, pal.length+1);
                pal[pal.length-1] = arr[i];
            }
        }
        if(pal.length>0)
        {
            return pal;
        }
        return null;
    }
}

/* Check a number is perfect or not

 * Input : 6
 * Output : Perfect Number
 * 
 * Explaination
 * --------------------------
 * The divisors of 6 = 1,2,3. 1+2+3 = 6
 * Sum of the factors is equal to the given number. So this is perfect
 * 
 * Input : 8
 * Output : Not Perfect Number
 * 
 * Explaination
 * -------------------------
 * Factors of 8 = 1,2,4, but 1+2+4 = 7 not equal to 8.
 */

import java.util.*;
public class PerfectNumber {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        boolean check = isPerfect(n);
        if(check == true)
        {
            System.out.println("Perfect Number");
        }
        else
        {
            System.out.println("Not Perfect Number");
        }
    }
    public static boolean isPerfect(int n)
    {
        int sum = 0;
        for (int i = 1; i < n; i++) 
        {
            if(n % i == 0)
            {
                sum += i;
            }
        }
        if(sum == n)
        {
            return true;
        }
        return false;
    }
}

