/*
 * Write a Java program that takes two user input integers m and n and prints the multiplication table from 1 to n for the 
 * number m. The program should use nested for loops to generate the table.
 * 
 * Sample Input:
 * --------------------
 * 3 5
 * 
 * Sample Output:
 * --------------------
 *  3 x 1 = 3
    3 x 2 = 6
    3 x 3 = 9
    3 x 4 = 12
    3 x 5 = 15

 * Explanation:
   --------------------
   The input integers are m=3 and n=5. The program generates the multiplication table for 3 from 1 to 5. 

 */

import java.util.*;
public class table {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        int n = sc.nextInt();
        for (int i = 1; i <= n; i++) {
            System.out.println(k+" x "+i+" = "+k*i);
        }
    }
}

import java.util.*;
class test
{
    public static void main(String[] args)
    {
        Scanner sc = new Scanner(System.in);
        Footwear[] ff= new Footwear[5];
        for(int i=0;i<5;i++)
        {
            int id= sc.nextInt();
            sc.nextLine();
            String name= sc.nextLine();
            String type= sc.nextLine();
            int price= sc.nextInt();
            sc.nextLine();
            ff[i]=new Footwear(id,name,type,price);
        }
        String gg= sc.nextLine();
        String hh =sc.nextLine();
        int count =getcount( ff, gg);
        if(count>0)
        {
            System.out.println(count);
        }
        else
        {
            System.out.println("Footwear not available");
        }

        Footwear temp= getSecondHighestPriceByBrand( ff, hh);
        if(temp==null)
        {
            System.out.println("Brand not available");
        }
        else
        {
            System.out.println(temp.price);
        }
    }
    public static int getcount(Footwear[] ff,String gg)
    {
        int count=0;
        for(Footwear data:ff)
        {
            if(data.type.equalsIgnoreCase(gg))
            {
                count++;
            }
        }
        return count;
    }

    public static   Footwear getSecondHighestPriceByBrand(Footwear[] ff,String hh)
    {
         int count1=0;
        for(int i=0;i<ff.length;i++)
        {
            if(ff[i].name.equalsIgnoreCase(hh))
            {
                count1++;
            }
        }
        int[] vv= new int[count1];
        int count2=0;
        for(int i=0;i<ff.length;i++)
        {
            if(ff[i].name.equalsIgnoreCase(hh))
            {
                vv[count2]=ff[i].price;
                count2++;
            }
        }
        Arrays.sort(vv);
        int hhh = vv[vv.length-2];
        for(int i=0;i<ff.length;i++)
        {
            if(ff[i].price==hhh)
            {
                return ff[i];
            }
        }
        return null;
    }
}
